// Turn the incoming request into ONE item that carries the video as binary "video"
// (or a URL for the next node to download). Only the first input item is used:
// one execution publishes one reel.
const cfg = $('Config').first().json;

if (!/^\d+$/.test(String(cfg.ig_user_id || ''))) {
  throw new Error('Config.ig_user_id is not set. Put the numeric ID of your Instagram professional account into the Config node.');
}
if (!/^v\d+\.\d+$/.test(String(cfg.graph_version || ''))) {
  throw new Error('Config.graph_version must look like "v23.0".');
}

// Manual test run or a call from another workflow?
const src = $('Test Input').isExecuted
  ? $('Test Input').first()
  : $('When Called by Another Workflow').first();
const input = src.json || {};
const binaries = src.binary || {};

const toBool = (v, dflt) => {
  if (v === undefined || v === null || v === '') return dflt;
  if (typeof v === 'boolean') return v;
  return !['false', '0', 'no', 'off'].includes(String(v).trim().toLowerCase());
};

// Caption limits from Meta's IG User Media reference: 2200 chars, 30 hashtags, 20 @tags.
const caption = input.caption == null ? '' : String(input.caption);
if (caption.length > 2200) throw new Error(`Caption is ${caption.length} characters; Instagram allows at most 2200.`);
const hashtags = (caption.match(/(^|\s)#[^\s#]+/g) || []).length;
if (hashtags > 30) throw new Error(`Caption has ${hashtags} hashtags; Instagram allows at most 30.`);
const mentions = (caption.match(/(^|\s)@[A-Za-z0-9._]+/g) || []).length;
if (mentions > 20) throw new Error(`Caption has ${mentions} @mentions; Instagram allows at most 20.`);

// Optional cover. Meta downloads cover_url itself, so it must be publicly reachable.
const cover_url = input.cover_url ? String(input.cover_url).trim() : '';
if (cover_url && !/^https?:\/\//i.test(cover_url)) throw new Error('cover_url must be a public http(s) URL.');
let thumb_offset = null;
if (input.thumb_offset !== undefined && input.thumb_offset !== null && input.thumb_offset !== '') {
  thumb_offset = Number(input.thumb_offset);
  if (!Number.isInteger(thumb_offset) || thumb_offset < 0) throw new Error('thumb_offset must be a whole number of milliseconds (0 or more).');
}

const options = {
  caption,
  share_to_feed: toBool(input.share_to_feed, true),
  also_story: toBool(input.also_story, false),
  cover_url: cover_url || null,
  thumb_offset,
};

// (a) Binary video on the incoming item.
const keys = Object.keys(binaries);
let binKey = null;
if (input.binary_property) {
  binKey = String(input.binary_property);
  if (!binaries[binKey]) throw new Error(`binary_property "${binKey}" not found on the input item. Available: ${keys.join(', ') || 'none'}.`);
} else if (binaries.video) binKey = 'video';
else if (binaries.data) binKey = 'data';
else if (keys.length === 1) binKey = keys[0];
else if (keys.length > 1) throw new Error(`The input item has several binary properties (${keys.join(', ')}). Set binary_property to the one that holds the video.`);

if (binKey) {
  return [{ json: { ...options, source: 'binary', needs_download: false }, binary: { video: binaries[binKey] } }];
}

// (b) A URL. n8n downloads it in the next node; Meta never sees this URL.
if (input.video_url) {
  const u = String(input.video_url).trim();
  if (!/^https?:\/\//i.test(u)) throw new Error('video_url must start with http:// or https://');
  return [{ json: { ...options, source: 'url', needs_download: true, download_url: u } }];
}

// (c) A file on the n8n host. Needs NODE_FUNCTION_ALLOW_BUILTIN=fs.
if (input.video_path) {
  const p = String(input.video_path);
  const root = String(cfg.allowed_video_dir || '').replace(/\/+$/, '');
  if (!root) throw new Error('Config.allowed_video_dir is empty; set it to the folder video_path may read from.');
  if (!p.startsWith(root + '/') || p.split('/').includes('..')) {
    throw new Error(`video_path must be inside ${root}/ (Config.allowed_video_dir).`);
  }
  let fs;
  try { fs = require('fs'); } catch (e) {
    throw new Error('video_path needs the fs module: set NODE_FUNCTION_ALLOW_BUILTIN=fs (on the task runner if you use external runners), or pass the video as binary / video_url.');
  }
  if (!fs.existsSync(p)) throw new Error(`video_path not found: ${p}`);
  const name = p.split('/').pop();
  const mime = /\.mov$/i.test(name) ? 'video/quicktime' : 'video/mp4';
  const bin = await this.helpers.prepareBinaryData(fs.readFileSync(p), name, mime);
  return [{ json: { ...options, source: 'path', needs_download: false }, binary: { video: bin } }];
}

throw new Error('No video given. Pass a binary video, video_url or video_path (see README).');

// Measure the file, apply Meta's documented size limits and build the Reels container parameters.
const cfg = $('Config').first().json;
const p = $('Normalize Input').first().json;
const item = $input.first();
const bin = item.binary && item.binary.video;
if (!bin) throw new Error('No "video" binary to upload (the download returned nothing?).');

// rupload needs the exact byte count in the file_size header.
let bytes = Number(bin.bytes);
if (!Number.isFinite(bytes) || bytes <= 0) {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'video');
  bytes = buf.length;
}
if (!bytes) throw new Error('The video file is empty (0 bytes).');

const MB = 1000 * 1000;
const reelMax = Number(cfg.max_reel_mb) || 300;
if (bytes > reelMax * MB) throw new Error(`Video is ${(bytes / MB).toFixed(1)} MB; the Reels limit is ${reelMax} MB.`);

let story_skipped = null;
const storyMax = Number(cfg.max_story_mb) || 100;
if (p.also_story && bytes > storyMax * MB) {
  story_skipped = `video is ${(bytes / MB).toFixed(1)} MB, above the ${storyMax} MB story limit`;
}

// Downloads sometimes come back as application/octet-stream; send a video content type.
const video = { ...bin };
if (!/^video\//.test(String(video.mimeType || ''))) {
  video.mimeType = /\.mov$/i.test(String(video.fileName || '')) ? 'video/quicktime' : 'video/mp4';
}

// Optional container parameters. If both are given Meta uses cover_url and ignores thumb_offset.
const extra_params = {};
if (p.caption) extra_params.caption = p.caption;
if (p.cover_url) extra_params.cover_url = p.cover_url;
else if (p.thumb_offset !== null && p.thumb_offset !== undefined) extra_params.thumb_offset = String(p.thumb_offset);

return [{
  json: {
    share_to_feed: p.share_to_feed ? 'true' : 'false',
    extra_params,
    also_story: Boolean(p.also_story) && !story_skipped,
    story_skipped,
    bytes,
    file_name: video.fileName || null,
  },
  binary: { video },
}];

// A resumable container answers with { id, uri }. The bytes go to `uri` (rupload.facebook.com),
// so Meta never has to download anything from your server.
const c = $input.first().json || {};
if (!c.id || !c.uri) {
  throw new Error('Meta did not return an upload URI for the reel container: ' + JSON.stringify(c).slice(0, 300));
}
const prep = $('Prepare Upload').first();
return [{
  json: { container_id: String(c.id), uri: c.uri, bytes: prep.json.bytes },
  binary: { video: prep.binary.video },
}];

// One status poll -> finished | pending | failed | timeout.
const cfg = $('Config').first().json;
const s = $input.first().json || {};
const containerId = String($('Create Reel Container').first().json.id);
const attempt = $runIndex + 1;
const max = Math.max(1, Number(cfg.max_poll_attempts) || 6);
const waited = attempt * (Number(cfg.poll_interval_seconds) || 60);

let state = 'pending';
let message = '';
if (s.status_code === 'FINISHED') {
  state = 'finished';
} else if (s.status_code === 'ERROR' || s.status_code === 'EXPIRED') {
  // For ERROR, Meta puts the error subcode into `status`.
  state = 'failed';
  message = `Meta could not process the reel video: status_code=${s.status_code}` +
    (s.status ? `, status=${s.status}` : '') + ` (container ${containerId}).`;
} else if (attempt >= max) {
  state = 'timeout';
  message = `Reel container ${containerId} is still ${s.status_code || 'not ready'} after ${attempt} checks (~${waited}s). ` +
    'It can still be published with media_publish until it expires (24 h); raise max_poll_attempts if this happens often.';
}
return [{ json: { state, status_code: s.status_code || null, status: s.status || null, attempt, container_id: containerId, message } }];

// The reel is live. Collect its id and link; the permalink lookup is allowed to fail.
const prep = $('Prepare Upload').first().json;
const pub = $('Publish Reel').first().json || {};
const media_id = pub.id != null ? String(pub.id) : '';
if (!media_id) throw new Error('media_publish did not return a media id: ' + JSON.stringify(pub).slice(0, 300));
const link = $input.first().json || {};
return [{
  json: {
    media_id,
    permalink: link.permalink || null,
    timestamp: link.timestamp || null,
    also_story: prep.also_story,
    story_skipped: prep.story_skipped || null,
  },
}];

// Same file, second container (media_type=STORIES). Nothing in the story branch may fail the run:
// problems are passed on and reported in story.error.
// Readable reason from a failed item. Depending on the n8n version and node, the error sits on
// item.error or in json.error / json (older Graph node). Meta's response body is recovered from
// n8n's "<status> - <body>" text when possible.
const errText = (it) => {
  const j = (it && it.json) || {};
  const e = (it && it.error) || (j.error && typeof j.error === 'object' ? j.error : null);
  let body = null;
  for (const t of [e && e.cause && e.cause.message, e && e.description]) {
    const m = typeof t === 'string' && t.match(/^\d{3} - ([\s\S]+)$/);
    if (!m) continue;
    try {
      body = JSON.parse(m[1]);
      if (typeof body === 'string') body = JSON.parse(body);
    } catch (x) { body = null; }
    if (body && typeof body === 'object') break;
    body = null;
  }
  const g = (body && (body.error || body.debug_info)) ||
    (j.message && (j.code || j.error_subcode || j.type) ? j : null);
  if (g && g.message) {
    return g.message + (g.error_user_msg ? ' - ' + g.error_user_msg : '') +
      (g.code ? ` (code ${g.code}${g.error_subcode ? ', subcode ' + g.error_subcode : ''})` : '');
  }
  if (e && (e.description || e.message)) return String(e.description || e.message);
  if (typeof j.error === 'string') return j.error;
  if (j.message) return String(j.message);
  return JSON.stringify(j).slice(0, 300);
};
const it = $input.first();
const c = it.json || {};
if (!c.id || !c.uri || it.error) {
  return [{ json: { story_error: 'story container could not be created: ' + errText(it) } }];
}
const prep = $('Prepare Upload').first();
return [{
  json: { container_id: String(c.id), uri: c.uri, bytes: prep.json.bytes },
  binary: { video: prep.binary.video },
}];

// One story status poll -> finished | pending | failed | timeout (never throws).
// Readable reason from a failed item. Depending on the n8n version and node, the error sits on
// item.error or in json.error / json (older Graph node). Meta's response body is recovered from
// n8n's "<status> - <body>" text when possible.
const errText = (it) => {
  const j = (it && it.json) || {};
  const e = (it && it.error) || (j.error && typeof j.error === 'object' ? j.error : null);
  let body = null;
  for (const t of [e && e.cause && e.cause.message, e && e.description]) {
    const m = typeof t === 'string' && t.match(/^\d{3} - ([\s\S]+)$/);
