      if (typeof body === 'string') body = JSON.parse(body);
    } catch (x) { body = null; }
    if (body && typeof body === 'object') break;
    body = null;
  }
  const g = (body && (body.error || body.debug_info)) ||
    (j.message && (j.code || j.error_subcode || j.type) ? j : null);
  if (g && g.message) {
    return g.message + (g.error_user_msg ? ' - ' + g.error_user_msg : '') +
      (g.code ? ` (code ${g.code}${g.error_subcode ? ', subcode ' + g.error_subcode : ''})` : '');
  }
  if (e && (e.description || e.message)) return String(e.description || e.message);
  if (typeof j.error === 'string') return j.error;
  if (j.message) return String(j.message);
  return JSON.stringify(j).slice(0, 300);
};
const cfg = $('Config').first().json;
const it = $input.first();
const s = it.json || {};
const attempt = $runIndex + 1;
const max = Math.max(1, Number(cfg.story_max_poll_attempts) || 3);

let state = 'pending';
let message = '';
if (s.status_code === 'FINISHED') {
  state = 'finished';
} else if (s.status_code === 'ERROR' || s.status_code === 'EXPIRED') {
  state = 'failed';
  message = `Meta could not process the story video: status_code=${s.status_code}` + (s.status ? `, status=${s.status}` : '');
} else if (!s.status_code && (it.error || s.message || s.error)) {
  state = 'failed';
  message = 'could not read the story container status: ' + errText(it).slice(0, 300);
} else if (attempt >= max) {
  state = 'timeout';
  message = `story container still ${s.status_code || 'not ready'} after ${attempt} checks`;
}
return [{ json: { state, status_code: s.status_code || null, status: s.status || null, attempt, message } }];

// Reached from every story exit (published, container/upload/status error, timeout).
// Readable reason from a failed item. Depending on the n8n version and node, the error sits on
// item.error or in json.error / json (older Graph node). Meta's response body is recovered from
// n8n's "<status> - <body>" text when possible.
const errText = (it) => {
  const j = (it && it.json) || {};
  const e = (it && it.error) || (j.error && typeof j.error === 'object' ? j.error : null);
  let body = null;
  for (const t of [e && e.cause && e.cause.message, e && e.description]) {
    const m = typeof t === 'string' && t.match(/^\d{3} - ([\s\S]+)$/);
    if (!m) continue;
    try {
      body = JSON.parse(m[1]);
      if (typeof body === 'string') body = JSON.parse(body);
    } catch (x) { body = null; }
    if (body && typeof body === 'object') break;
    body = null;
  }
  const g = (body && (body.error || body.debug_info)) ||
    (j.message && (j.code || j.error_subcode || j.type) ? j : null);
  if (g && g.message) {
    return g.message + (g.error_user_msg ? ' - ' + g.error_user_msg : '') +
      (g.code ? ` (code ${g.code}${g.error_subcode ? ', subcode ' + g.error_subcode : ''})` : '');
  }
  if (e && (e.description || e.message)) return String(e.description || e.message);
  if (typeof j.error === 'string') return j.error;
  if (j.message) return String(j.message);
  return JSON.stringify(j).slice(0, 300);
};
const it = $input.first();
const j = it.json || {};
const published = j.id != null && !it.error && !j.error && !j.message && !j.story_error && !j.state;
let story;
if (published) {
  story = { ok: true, media_id: String(j.id) };
} else {
  // story_error: container step; state/message: status loop; anything else: failed upload or publish call
  const why = j.story_error || (j.state ? j.message : '') || errText(it);
  story = { ok: false, error: String(why || 'unknown error').slice(0, 500) };
}
return [{ json: { story } }];

// Final result returned to the calling workflow (last node = sub-workflow output).
const reel = $('Reel Result').first().json;
let story = null; // null = not requested
if ($('Story Result').isExecuted) story = $('Story Result').first().json.story;
else if (reel.story_skipped) story = { ok: false, error: reel.story_skipped };
return [{ json: { media_id: reel.media_id, permalink: reel.permalink, timestamp: reel.timestamp, story } }];
